INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q459939', 'Kofun period', 'The Kofun period (古墳時代, Kofun jidai) is an era in the history of Japan from about 300 to 538 AD, the date of the introduction of Buddhism in Japan, following the Yayoi period. The Kofun period and the subsequent Asuka period are sometimes collectively referred to as the Yamato period.', 250, NULL, NULL, 538, NULL, NULL, 'year', '250–538', 74, 'https://en.wikipedia.org/wiki/Kofun_period'),
  ('Q210688', 'Asuka period', 'The Asuka period (飛鳥時代, Asuka jidai; Japanese pronunciation: [a.sɯ̥.ka ((d)ʑiꜜ.dai)]) was a period in the history of Japan lasting from 538 to 710, although its beginning could be said to overlap with the preceding Kofun period. The Yamato polity evolved greatly during the Asuka period, which is named after the Asuka region, about 25 km (16 mi) south of the modern city of Nara.', 538, NULL, NULL, 710, NULL, NULL, 'year', '538–710', 73, 'https://en.wikipedia.org/wiki/Asuka_period'),
  ('Q189178', 'Nara period', 'The Nara period (奈良時代, Nara jidai; Japanese pronunciation: [na.ɾa (d)ʑiꜜ.dai]) of the history of Japan covers the years from 710 to 794. It succeeded the Asuka period and is followed by the Heian period.', 710, NULL, NULL, 794, NULL, NULL, 'year', '710–794', 78, 'https://en.wikipedia.org/wiki/Nara_period'),
  ('Q193292', 'Heian period', 'The Heian period (平安時代, Heian jidai) is the last division of classical Japanese history, running from 794 to 1185. It followed the Nara period, beginning when the 50th emperor, Emperor Kammu, moved the capital of Japan to Heian-kyō (modern Kyoto).', 794, NULL, NULL, 1185, NULL, NULL, 'year', '794–1185', 79, 'https://en.wikipedia.org/wiki/Heian_period'),
  ('Q842357', 'Hōgen rebellion', 'The Hōgen rebellion (保元の乱, Hōgen no ran; July 28 – August 16, 1156) was a short civil war fought in order to resolve a dispute about Japanese Imperial succession. The dispute was also about the degree of control exercised by the Fujiwara clan who had become hereditary Imperial regents during the Heian period.', 1156, 7, 29, 1156, 8, 16, 'day', '29 July 1156 – 16 August 1156', 62, 'https://en.wikipedia.org/wiki/H%C5%8Dgen_rebellion'),
  ('Q737542', 'Genpei War', 'The Genpei War (源平合戦, Genpei Kassen, Genpei-Gassen; 1180–1185) was a national civil war between the Taira and Minamoto clans during the late Heian period of Japan. It resulted in the downfall of the Taira and the establishment of the Kamakura shogunate under Minamoto no Yoritomo, who appointed himself as Shōgun in 1192, governing Japan as a military dictator from the eastern city of Kamakura.', 1180, NULL, NULL, 1185, NULL, NULL, 'year', '1180–1185', 69, 'https://en.wikipedia.org/wiki/Genpei_War'),
  ('Q236205', 'Kamakura period', 'The Kamakura period (鎌倉時代, Kamakura jidai; 1185–1333) is a period of Japanese history that marks the governance by the Kamakura shogunate, officially established in 1192 in Kamakura by the first shōgun Minamoto no Yoritomo after the conclusion of the Genpei War, which saw the struggle between the Taira and Minamoto clans. The period is known for the emergence of the samurai, the warrior caste, and for the establishment of feudalism in Japan.', 1185, NULL, NULL, 1333, NULL, NULL, 'year', '1185–1333', 72, 'https://en.wikipedia.org/wiki/Kamakura_period'),
  ('Q208156', 'Mongol invasions of Japan', 'Major military efforts were taken by Kublai Khan of the Yuan dynasty in 1274 and 1281 to conquer the Japanese archipelago after the submission of the Korean kingdom of Goryeo to vassaldom. Ultimately a failure, the invasion attempts are of macro-historical importance because they set a limit on Mongol expansion and rank as nation-defining events in the history of Japan.', 1274, NULL, NULL, NULL, NULL, NULL, 'year', '1274', 74, 'https://en.wikipedia.org/wiki/Mongol_invasions_of_Japan'),
  ('Q334845', 'Muromachi period', 'The Muromachi period or Muromachi era (室町時代, Muromachi jidai), also known as the Ashikaga period or Ashikaga era (足利時代, Ashikaga jidai), is a division of Japanese history running from approximately 1336 to 1573. The period marks the governance of the Muromachi or Ashikaga shogunate (Muromachi bakufu or Ashikaga bakufu), which was officially established in 1338 by the first Muromachi shōgun, Ashikaga Takauji, two years after the brief Kenmu Restoration (1333–1336) of imperial rule was brought to a close.', 1336, NULL, NULL, 1573, NULL, NULL, 'year', '1336–1573', 74, 'https://en.wikipedia.org/wiki/Muromachi_period'),
  ('Q204023', 'Sengoku period', 'The Sengoku period (戦国時代, Sengoku jidai; Japanese pronunciation: [seŋ.ɡo.kɯ (d)ʑiꜜ.dai, -ŋo.kɯ-] lit. ''Warring States period'') was the period in Japanese history in which civil wars and social upheavals took place almost continuously in the 15th and 16th centuries. The Kyōtoku incident (1454), Ōnin War (1467), or Meiō incident (1493) are generally chosen as the period''s start date, but there are many competing historiographies for its end date, ranging from 1568, the date of Oda Nobunaga''s march on Kyoto, to the suppression of the Shimabara Rebellion in 1638, deep into what was…', 1467, NULL, NULL, 1590, NULL, NULL, 'year', '1467–1590', 76, 'https://en.wikipedia.org/wiki/Sengoku_period'),
  ('Q385676', 'Ōnin War', 'The Ōnin War (応仁の乱, Ōnin no Ran), also known as the Upheaval of Ōnin and Ōnin-Bunmei war, was a civil war that lasted from 1467 to 1477, during the Muromachi period in Japan. Ōnin refers to the Japanese era during which the war started; the war ended during the Bunmei era.', 1467, NULL, NULL, 1477, NULL, NULL, 'year', '1467–1477', 67, 'https://en.wikipedia.org/wiki/%C5%8Cnin_War'),
  ('Q349422', 'Battle of Okehazama', 'The Battle of Okehazama (桶狭間の戦い, Okehazama-no-tatakai) took place on 12 June 1560 in Owari Province, in today''s Aichi Prefecture. In this battle, the heavily outnumbered Oda clan troops, commanded by Oda Nobunaga, defeated Imagawa Yoshimoto and established Oda as one of the front-running warlords in the Sengoku period.', 1560, 6, 12, NULL, NULL, NULL, 'day', '12 June 1560', 64, 'https://en.wikipedia.org/wiki/Battle_of_Okehazama'),
  ('Q319531', 'Azuchi-Momoyama period', 'The Azuchi–Momoyama period (安土桃山時代, Azuchi–Momoyama jidai) or Oda-Toyotomi period (織田・豊臣時代) or also Shokuhō period (織豊時代) was the final phase of the Sengoku period (戦国時代, Sengoku jidai) in Japanese history from 1568 to 1603. After the outbreak of the Ōnin War in 1467, the power of the Ashikaga Shogunate effectively collapsed, marking the start of the chaotic Sengoku period.', 1568, NULL, NULL, 1600, NULL, NULL, 'year', '1568–1600', 73, 'https://en.wikipedia.org/wiki/Azuchi%E2%80%93Momoyama_period'),
  ('Q690464', 'Battle of Mikatagahara', 'The Battle of Mikatagahara (三方ヶ原の戦い, Mikatagahara no tatakai) took place during the Sengoku period of Japan between Takeda Shingen and Tokugawa Ieyasu in Tōtōmi Province on January 25, 1573. Shingen attacked Ieyasu on the plain of Mikatagahara north of Hamamatsu during his campaign against Oda Nobunaga while seeking a route from Kōfu to Kyoto.', 1573, 1, 25, NULL, NULL, NULL, 'day', '25 January 1573', 61, 'https://en.wikipedia.org/wiki/Battle_of_Mikatagahara'),
  ('Q428369', 'Battle of Nagashino', 'The Battle of Nagashino (長篠の戦い, Nagashino no Tatakai) was a famous battle in Japanese history, fought in 1575 at Nagashino in Mikawa Province (present-day Nagashino, Shinshiro, Aichi Prefecture). The allied forces of Oda Nobunaga and Tokugawa Ieyasu (38,000) fought against Takeda Katsuyori''s forces (15,000) and the allied forces won a crushing victory over the Takeda clan.', 1575, 6, 28, NULL, NULL, NULL, 'day', '28 June 1575', 65, 'https://en.wikipedia.org/wiki/Battle_of_Nagashino'),
  ('Q234188', 'Battle of Sekigahara', 'The Battle of Sekigahara (Shinjitai: 関ヶ原の戦い; Kyūjitai: 關ヶ原の戰い, Hepburn romanization: Sekigahara no Tatakai) was an important battle in Japan which occurred on October 21, 1600 (Keichō 5, 15th day of the 9th month) in what is now Gifu Prefecture, Japan, at the end of the Sengoku period. This battle was fought by the forces of Tokugawa Ieyasu against a coalition loyal to the Toyotomi clan, led by Ishida Mitsunari on behalf of the young child Toyotomi Hideyori, from which several commanders defected before or during the battle, leading to a Tokugawa victory.', 1600, 10, 21, NULL, NULL, NULL, 'day', '21 October 1600', 73, 'https://en.wikipedia.org/wiki/Battle_of_Sekigahara'),
  ('Q184963', 'Edo period', 'The Edo period, also known as the Tokugawa period, is the period between 1600 or 1603 and 1868 in the history of Japan, when the country was under the rule of the Tokugawa shogunate and some 300 regional daimyo, or feudal lords. Emerging from the chaos of the Sengoku period, the Edo period was characterized by prolonged peace and stability, urbanization and economic growth, strict social order, isolationist foreign policies, and popular enjoyment of arts and culture.', 1603, NULL, NULL, 1868, NULL, NULL, 'year', '1603–1868', 81, 'https://en.wikipedia.org/wiki/Edo_period'),
  ('Q475780', 'Siege of Osaka', 'The siege of Osaka (大坂の役, Ōsaka no Eki; or, more commonly, 大坂の陣 Ōsaka no Jin) was a series of battles undertaken by the Japanese Tokugawa shogunate against the Toyotomi clan, ending in that clan''s destruction. Divided into two stages, the winter campaign and the summer campaign, it lasted from 1614 to 1615.', 1614, 11, 8, 1615, 6, NULL, 'day', '8 November 1614 – June 1615', 66, 'https://en.wikipedia.org/wiki/Siege_of_Osaka'),
  ('Q804558', 'Bakumatsu', 'Bakumatsu (幕末; Japanese pronunciation: [ba.kɯ.ma.tsɯ], ''end of the bakufu'') were the final years of the Edo period when the Tokugawa shogunate ended. Between 1853 and 1867, under foreign diplomatic and military pressure, Japan ended its isolationist foreign policy known as sakoku and changed from a feudal Tokugawa shogunate to the modern empire of the Meiji government.', 1853, NULL, NULL, 1868, NULL, NULL, 'year', '1853–1868', 65, 'https://en.wikipedia.org/wiki/Bakumatsu'),
  ('Q497189', 'Treaty of Shimoda', 'The Treaty of Shimoda (Japanese: 下田条約, Hepburn: Shimoda Jouyaku), formally the Treaty of Commerce and Navigation between Japan and Russia (日露和親条約, Nichi-Ro Washin Jouyaku), was the first treaty between the Russian Empire and the Empire of Japan (then under the Tokugawa shogunate), signed on February 7, 1855. Signed shortly after the Convention of Kanagawa between Japan and the United States, it effectively meant the end of Japan''s 220-year-old policy of national seclusion (sakoku) by opening the ports of Nagasaki, Shimoda and Hakodate to Russian vessels.', 1855, 2, 7, NULL, NULL, NULL, 'day', '7 February 1855', 64, 'https://en.wikipedia.org/wiki/Treaty_of_Shimoda'),
  ('Q771451', 'Convention of Kanagawa', 'The Convention of Kanagawa, also known as the Kanagawa Treaty (神奈川条約, Kanagawa Jōyaku) or the Japan–US Treaty of Peace and Amity (日米和親条約, Nichibei Washin Jōyaku), was a treaty signed between the United States and the Tokugawa Shogunate on March 31, 1854. Signed under threat of force, it effectively meant the end of Japan''s 220-year-old policy of national seclusion (sakoku) by opening the ports of Shimoda and Hakodate to American vessels.', 1864, 3, 31, NULL, NULL, NULL, 'day', '31 March 1864', 70, 'https://en.wikipedia.org/wiki/Convention_of_Kanagawa'),
  ('Q1193959', 'Battle of Toba-Fushimi', 'The Battle of Toba–Fushimi (鳥羽・伏見の戦い, Toba-Fushimi no Tatakai) occurred between pro-Imperial and Tokugawa shogunate forces during the Boshin War in Japan. The battle started on 27 January 1868 (or fourth year of Keiō, first month, 3rd day, according to the lunar calendar), when the forces of the shogunate and the allied forces of Chōshū, Satsuma and Tosa Domains clashed near Fushimi, a town near Kyoto, the sacred capital, and fighting progressed to the Toba road leading to Osaka, with the initial rout of the Satsuma from Fushimi.', 1868, 1, 31, NULL, NULL, NULL, 'day', '31 January 1868', 61, 'https://en.wikipedia.org/wiki/Battle_of_Toba%E2%80%93Fushimi'),
  ('Q3125096', 'Meiji era', 'The Meiji era (明治時代, Meiji jidai) was an era of Japanese history that extended from October 23, 1868, to July 30, 1912. The Meiji era dominated the first half of the Empire of Japan, when the Japanese people moved from being an isolated feudal society at risk of colonization by Western imperial powers to the new paradigm of a modern, industrialized nation state and emergent great power, influenced by Western scientific, technological, philosophical, political, legal, and aesthetic ideas.', 1868, 10, 23, 1912, 7, 30, 'day', '23 October 1868 – 30 July 1912', 80, 'https://en.wikipedia.org/wiki/Meiji_era'),
  ('Q159950', 'Russo-Japanese War', 'The Russo-Japanese War (8 February 1904 – 5 September 1905) was fought between the Russian Empire and the Empire of Japan over rival imperial ambitions in Manchuria and the Korean Empire. The major land battles of the war were fought on the Liaodong Peninsula and near Mukden in Southern Manchuria, with naval battles taking place in the Yellow Sea and the Sea of Japan.', 1904, 2, 8, 1905, 9, 5, 'day', '8 February 1904 – 5 September 1905', 86, 'https://en.wikipedia.org/wiki/Russo-Japanese_War'),
  ('Q329174', 'Taishō era', 'The Taishō era (大正時代, Taishō jidai; [taiɕoː dʑidai] ) was a period in the history of Japan dating from July 30, 1912, to December 25, 1926, coinciding with the reign of Emperor Taishō. The new emperor brought on the shift in political power from the old oligarchic group of elder statesmen (or genrō) to the Imperial Diet of Japan and the democratic parties.', 1912, 7, 30, 1926, 12, 25, 'day', '30 July 1912 – 25 December 1926', 74, 'https://en.wikipedia.org/wiki/Taish%C5%8D_era'),
  ('Q696111', 'Rice Riots of 1918', 'The rice riots of 1918 (Japanese: 米騒動, Hepburn: kome sōdō) were a series of popular disturbances that swept across Japan from July to September 1918. Lasting for over eight weeks, the riots were the largest, most widespread, and most violent popular uprising in modern Japanese history, ultimately leading to the collapse of the Terauchi Masatake administration.', 1918, NULL, NULL, 1918, 9, NULL, 'year', '1918', 66, 'https://en.wikipedia.org/wiki/Rice_riots_of_1918'),
  ('Q327567', 'Shōwa era', 'The Shōwa era (昭和時代, Shōwa jidai; [ɕoːwadʑidai] ) was a period of Japanese history corresponding to the reign of Emperor Shōwa (Hirohito) from December 25, 1926, until his death on January 7, 1989. It was preceded by the Taishō era and succeeded by the Heisei era.', 1926, 12, 25, 1989, 1, 7, 'day', '25 December 1926 – 7 January 1989', 69, 'https://en.wikipedia.org/wiki/Sh%C5%8Dwa_era'),
  ('Q696389', 'Soviet–Japanese border conflicts', 'The Soviet–Japanese border conflicts were a series of minor and major conflicts fought between the Soviet Union (led by Joseph Stalin), Mongolia (led by Khorloogiin Choibalsan) and Japan (led by Hirohito) in Northeast Asia from 1932 to 1939. The Japanese expansion in Northeast China created a common border between Japanese-occupied Manchuria and the Soviet Far East.', 1932, 3, 1, 1939, 9, 16, 'day', '1 March 1932 – 16 September 1939', 66, 'https://en.wikipedia.org/wiki/Soviet%E2%80%93Japanese_border_conflicts'),
  ('Q362', 'World War II', 'World War II, or the Second World War (1 September 1939 – 2 September 1945), was a global conflict between two coalitions: the Allies and the Axis powers. Nearly all of the world''s countries were involved, with many engaging in total war on an unprecedented scale.', 1939, 9, 1, 1945, 9, 2, 'day', '1 September 1939 – 2 September 1945', 100, 'https://en.wikipedia.org/wiki/World_War_II'),
  ('Q504347', 'Battle of the Philippine Sea', 'The Battle of the Philippine Sea was a major naval battle of World War II on 19–20 June 1944 that eliminated the Imperial Japanese Navy''s ability to conduct large-scale carrier actions. It took place during the United States'' amphibious reconquest of the Mariana Islands during the Pacific War.', 1944, 6, 19, 1944, 6, 20, 'day', '19 June 1944 – 20 June 1944', 71, 'https://en.wikipedia.org/wiki/Battle_of_the_Philippine_Sea'),
  ('Q180182', 'Battle of Iwo Jima', 'The Battle of Iwo Jima (硫黄島の戦い, Iōtō no Tatakai,or Iōjima no Tatakai; 19 February – 26 March 1945) was a major battle in which the United States Marine Corps (USMC), United States Navy (USN), and United States Army (USA) landed on and eventually captured the island of Iwo Jima from the Imperial Japanese Army (IJA) during World War II. The American invasion, designated Operation Detachment, had the goal of capturing the island with its two airfields: South Field and Central Field. The Japanese Army positions on the island were heavily fortified, with a dense network of bunkers, hidden…', 1945, 2, 8, 1945, 3, 26, 'day', '8 February 1945 – 26 March 1945', 79, 'https://en.wikipedia.org/wiki/Battle_of_Iwo_Jima'),
  ('Q192660', 'Battle of Okinawa', 'The Battle of Okinawa (Japanese: 沖縄戦, Hepburn: Okinawa-sen), codenamed Operation Iceberg, was a major battle of the Pacific War fought on the island of Okinawa by the United States Army and United States Marine Corps forces against the Imperial Japanese Army. The initial invasion of Okinawa on 1 April 1945 was the largest amphibious assault in the Pacific Theater of World War II. The Kerama Islands surrounding Okinawa were preemptively captured on 26 March 1945 by the U.S. Army 77th Infantry Division.', 1945, NULL, NULL, 1945, 6, 23, 'year', '1945', 77, 'https://en.wikipedia.org/wiki/Battle_of_Okinawa'),
  ('Q665554', 'Japanese Instrument of Surrender', 'The Japanese Instrument of Surrender was the printed agreement that formalized the surrender of Japan, marking the end of hostilities in World War II. It was signed by representatives from Japan and from the Allied nations: the United States, China, the United Kingdom, the Soviet Union, Australia, Canada, France, the Netherlands, and New Zealand. The signing took place on the deck of USS Missouri in Tokyo Bay just after 09:00 Japan Standard Time (JST) and took effect at 09:25 JST on 2 September 1945.', 1945, 9, 2, NULL, NULL, NULL, 'day', '2 September 1945', 69, 'https://en.wikipedia.org/wiki/Japanese_Instrument_of_Surrender'),
  ('Q696251', 'Occupation of Japan', 'Japan was occupied and administered by the Allies of World War II from the surrender of the Empire of Japan on September 2, 1945, at the war''s end until the Treaty of San Francisco took effect on April 28, 1952. The occupation, led by the American military with support from the British Commonwealth and under the supervision of the Far Eastern Commission, involved a total of nearly one million Allied soldiers.', 1945, 8, 28, NULL, NULL, NULL, 'day', '28 August 1945', 75, 'https://en.wikipedia.org/wiki/Occupation_of_Japan'),
  ('Q8663', 'Korean War', 'The Korean War (25 June 1950 – 27 July 1953) was an armed conflict fought on the Korean Peninsula between North Korea (Democratic People''s Republic of Korea; DPRK) and South Korea (Republic of Korea; ROK) and their allies. North Korea was supported by China and the Soviet Union, while South Korea was supported by the United Nations led by the United States under the auspices of the United Nations Command (UNC).', 1950, 6, 25, 1953, 7, 27, 'day', '25 June 1950 – 27 July 1953', 94, 'https://en.wikipedia.org/wiki/Korean_War'),
  ('Q392541', 'Treaty of San Francisco', 'The Treaty of San Francisco, also called the Treaty of Peace with Japan, re-established peaceful relations between Japan and the Allies on behalf of the United Nations by ending the legal state of war, military occupation and providing for redress for hostile actions up to and including World War II. It was signed by 49 nations on September 8, 1951, in San Francisco, United States, at the War Memorial Opera House. Italy and China were not invited, the latter due to disagreements on whether the Republic of China or the People''s Republic of China represented the Chinese people.', 1951, 9, 8, NULL, NULL, NULL, 'day', '8 September 1951', 76, 'https://en.wikipedia.org/wiki/Treaty_of_San_Francisco'),
  ('Q7445004', 'Security Treaty Between the United States and Japan', 'The Security Treaty between the United States and Japan (日本国とアメリカ合衆国との間の安全保障条約, Nippon-koku to Amerika Gasshūkoku to no aida no anzen hoshō jōyaku) was a treaty signed on September 8, 1951 in San Francisco, California, by representatives of the United States and Japan, in conjunction with the Treaty of San Francisco that ended World War II in Asia. The treaty was imposed on Japan by the United States as a condition for ending the occupation of Japan and restoring Japan''s sovereignty as a nation.', 1951, 9, 8, 1960, 6, 23, 'day', '8 September 1951 – 23 June 1960', 52, 'https://en.wikipedia.org/wiki/Security_Treaty_between_the_United_States_and_Japan'),
  ('Q694604', 'Treaty of Mutual Cooperation and Security Between the United States and Japan', 'The Treaty of Mutual Cooperation and Security between the United States and Japan, more commonly known as the U.S.–Japan Security Treaty in English and as the Anpo jōyaku or just Anpo in Japanese, is a treaty that permits the presence of U.S. military bases on Japanese soil, and commits the two nations to defend each other if one or the other is attacked "in the territories under the administration of Japan". Over time, it has established a military alliance between the United States and Japan.', 1960, 1, 19, NULL, NULL, NULL, 'day', '19 January 1960', 64, 'https://en.wikipedia.org/wiki/Treaty_of_Mutual_Cooperation_and_Security_between_the_United_States_and_Japan'),
  ('Q8420', '1964 Summer Olympics', 'The 1964 Summer Olympics, officially the Games of the XVIII Olympiad and commonly known as Tokyo 1964, were an international multi-sport event held from 10 to 24 October 1964 in Tokyo, Japan. Tokyo had been awarded the organization of the 1940 Summer Olympics, but this honor was subsequently passed to Helsinki due to Japan''s invasion of China, before ultimately being cancelled due to World War II. The 1964 Summer Olympics in Tokyo were the first Olympic Games held in the city and, as of 2021, the only ones to have spectators, as the 2020 Summer Olympics in Tokyo were conducted without…', 1964, 10, 10, 1964, 10, 24, 'day', '10 October 1964 – 24 October 1964', 84, 'https://en.wikipedia.org/wiki/1964_Summer_Olympics'),
  ('Q1119956', 'Expo ''70', 'The Japan World Exposition, Osaka, 1970 (日本万国博覧会, Nihon Bankoku Hakuran-kai) or Expo ''70 was a world''s fair held in Suita, Osaka Prefecture, Japan, between 15 March and 13 September 1970. Its theme was "Progress and Harmony for Mankind." In Japanese, Expo ''70 is often referred to as Ōsaka Banpaku (大阪万博).', 1970, NULL, NULL, 1970, 9, 13, 'year', '1970', 59, 'https://en.wikipedia.org/wiki/Expo_''70'),
  ('Q9646', '1972 Winter Olympics', 'The 1972 Winter Olympics, officially the XI Olympic Winter Games and commonly known as Sapporo 1972, were a winter multi-sport event held from February 3 to 13, 1972, in Sapporo, Hokkaido Prefecture, Japan. It was the first Winter Olympic Games to take place outside Europe and North America.', 1972, 2, NULL, 1972, 2, 13, 'month', 'February 1972 – 13 February 1972', 81, 'https://en.wikipedia.org/wiki/1972_Winter_Olympics'),
  ('Q18173', 'Japan Air Lines Flight 123', 'Japan Air Lines Flight 123 was a scheduled domestic passenger flight from Tokyo to Osaka, Japan. On the evening of Monday, August 12, 1985, the Boeing 747 flying the route suffered a severe structural failure and explosive decompression 12 minutes after takeoff.', 1985, 8, 12, NULL, NULL, NULL, 'day', '12 August 1985', 68, 'https://en.wikipedia.org/wiki/Japan_Air_Lines_Flight_123'),
  ('Q234510', 'Heisei era', 'The Heisei era (平成; Japanese: [heːseː] ) was the period of Japanese history corresponding to the reign of Emperor Akihito from 8 January 1989 until his abdication on 30 April 2019. The Heisei era started on 8 January 1989, the day after the death of the Emperor Hirohito, when his elder son, Akihito, acceded to the throne as the 125th Emperor of Japan.', 1989, 1, 8, 2019, 4, 30, 'day', '8 January 1989 – 30 April 2019', 73, 'https://en.wikipedia.org/wiki/Heisei_era'),
  ('Q214866', 'Great Hanshin Earthquake', 'The Kobe earthquake, also known as the Great Hanshin Earthquake (Japanese: 阪神淡路大震災, Hepburn: Hanshin-Awaji daishinsai), occurred on January 17, 1995, at 05:46:53 JST in the southern part of Hyōgo Prefecture, Japan, including the region of Hanshin. It measured 6.9 on the moment magnitude scale and had a maximum intensity of 7 on the JMA Seismic Intensity Scale (XI on the Modified Mercalli intensity scale).', 1995, 1, 17, NULL, NULL, NULL, 'day', '17 January 1995', 73, 'https://en.wikipedia.org/wiki/Kobe_earthquake'),
  ('Q1146739', 'Tokyo subway sarin attack', 'The Tokyo subway sarin attack (Japanese: 地下鉄サリン事件, Hepburn: Chikatetsu sarin jiken; lit. ''subway sarin incident'') was a domestic chemical terrorist attack perpetrated on 20 March 1995, in Tokyo, Japan, by members of the Aum Shinrikyo cult. In five coordinated attacks, the perpetrators released sarin, a nerve agent, on three lines of the Tokyo Metro (then Teito Rapid Transit Authority) during rush hour, killing 14 people, severely injuring 50 (some of whom later died), and causing temporary vision problems for nearly 1,000 others.', 1995, 3, 20, NULL, NULL, NULL, 'day', '20 March 1995', 73, 'https://en.wikipedia.org/wiki/Tokyo_subway_sarin_attack'),
  ('Q9664', '1998 Winter Olympics', 'The 1998 Winter Olympics, officially known as the XVIII Olympic Winter Games (Japanese: 第18回オリンピック冬季競技大会, Hepburn: Dai Jūhachi-kai Orinpikku Tōkikyōgi Taikai) and commonly known as Nagano 1998 (Japanese: 長野1998), were a winter multi-sport event held from 7 to 22 February 1998, mainly in Nagano Prefecture, Japan, with some events taking place in the nearby mountain communities of Hakuba, Karuizawa, Nozawa Onsen, and Yamanouchi. The city of Nagano had previously been a candidate to host the 1940 Winter Olympics (which were later cancelled), as well as the 1972 Winter Olympics, but had been…', 1998, 2, NULL, 1998, 2, 22, 'month', 'February 1998 – 22 February 1998', 82, 'https://en.wikipedia.org/wiki/1998_Winter_Olympics'),
  ('Q1377385', 'Tōkaimura criticality accident', 'The Tokaimura nuclear accidents were two nuclear incidents which occurred near the village of Tōkai, Ibaraki Prefecture, Japan. The first accident occurred on 11 March 1997, producing an explosion after an experimental batch of solidified nuclear waste caught fire at the Power Reactor and Nuclear Fuel Development Corporation (PNC) radioactive waste bituminisation facility.', 1999, 9, 30, NULL, NULL, NULL, 'day', '30 September 1999', 53, 'https://en.wikipedia.org/wiki/Tokaimura_nuclear_accidents'),
  ('Q47735', '2002 FIFA World Cup', 'The 2002 FIFA World Cup (Korean: 2002 FIFA 월드컵 한국/일본; Japanese: 2002 FIFAワールドカップ 韓国/日本) also branded as Korea Japan 2002, was the 17th FIFA World Cup, the quadrennial football world championship for men''s national teams organized by FIFA. It was held from 31 May to 30 June 2002 at sites in South Korea and Japan, with its final match hosted by Japan at International Stadium in Yokohama. A field of 32 teams qualified for this World Cup, which was the first to be held in Asia, the first to be held outside of the Americas or Europe, as well as the first to be hosted by more than one nation.', 2002, NULL, NULL, 2002, 6, 29, 'year', '2002', 87, 'https://en.wikipedia.org/wiki/2002_FIFA_World_Cup'),
  ('Q36204', '2011 Tōhoku earthquake and tsunami', 'On 11 March 2011, at 14:46:24 local time (UTC+9), a Mw 9.0–9.1 undersea megathrust earthquake occurred in the Pacific Ocean, 72 km (45 mi) east of the Oshika Peninsula of the Tōhoku region of Japan. It lasted approximately six minutes and caused a tsunami.', 2011, 3, 11, NULL, NULL, NULL, 'day', '11 March 2011', 86, 'https://en.wikipedia.org/wiki/2011_T%C5%8Dhoku_earthquake_and_tsunami'),
  ('Q171178', 'Fukushima Daiichi nuclear disaster', 'On 11 March 2011, a major nuclear accident started at the Fukushima Daiichi Nuclear Power Plant in Ōkuma, Fukushima, Japan. The direct cause was the Tōhoku earthquake and tsunami, which resulted in electrical grid failure and damaged nearly all of the power plant''s backup energy sources.', 2011, 3, 11, NULL, NULL, NULL, 'day', '11 March 2011', 81, 'https://en.wikipedia.org/wiki/Fukushima_nuclear_accident'),
  ('Q1136168', 'aftermath of the 2011 Tōhoku earthquake and tsunami', 'The aftermath of the 2011 Tōhoku earthquake and tsunami included both a humanitarian crisis and massive economic impacts. The tsunami created over 300,000 refugees in the Tōhoku region of Japan, and resulted in shortages of food, water, shelter, medicine and fuel for survivors.', 2011, 3, 11, NULL, NULL, NULL, 'day', '11 March 2011', 48, 'https://en.wikipedia.org/wiki/Aftermath_of_the_2011_T%C5%8Dhoku_earthquake_and_tsunami'),
  ('Q6862837', 'Minamata Convention on Mercury', 'The Minamata Convention on Mercury is an international treaty designed to protect human health and the environment from anthropogenic emissions and releases of mercury and mercury compounds. The convention was a result of three years of meeting and negotiating, after which the text of the convention was approved by delegates representing close to 140 countries on 19 January 2013 in Geneva and adopted and signed later that year on 10 October 2013 at a diplomatic conference held in Kumamoto, Japan.', 2013, 10, 10, NULL, NULL, NULL, 'day', '10 October 2013', 62, 'https://en.wikipedia.org/wiki/Minamata_Convention_on_Mercury'),
  ('Q23825118', '2016 Kumamoto earthquakes', 'The 2016 Kumamoto earthquakes (Japanese: 平成28年熊本地震, Hepburn: Heisei 28-nen Kumamoto jishin) were a series of earthquakes, including a magnitude 7.0 mainshock which struck at 01:25 JST on April 16, 2016 (16:25 UTC on April 15) beneath Kumamoto City of Kumamoto Prefecture in Kyushu Region, Japan, at a depth of about 10 kilometres (6.2 miles), and a foreshock earthquake with a magnitude 6.2 at 21:26 JST (12:26 UTC) on April 14, 2016, at a depth of about 11 kilometres (6.8 miles). In total, the two earthquakes killed 277 people and injured 2,809 others, a majority of them indirectly, This…', 2016, 4, NULL, 2016, 4, 16, 'month', 'April 2016 – 16 April 2016', 69, 'https://en.wikipedia.org/wiki/2016_Kumamoto_earthquakes'),
  ('Q62609017', 'Reiwa era', 'Reiwa (Japanese: 令和; pronounced [ɾeːwa] or [ɾeꜜːwa]) is the current and 232nd era of the official calendar of Japan. It began on 1 May 2019, the day on which Naruhito was enthroned as the 126th Emperor of Japan.', 2019, 5, 1, NULL, NULL, NULL, 'day', '1 May 2019', 75, 'https://en.wikipedia.org/wiki/Reiwa_era'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q181278', '2020 Summer Olympics', 'The 2020 Summer Olympics, officially the Games of the XXXII Olympiad and officially branded as Tokyo 2020, were an international multi-sport event held from 23 July to 8 August 2021, in Tokyo, Japan, with some of the preliminary sporting events beginning on 21 July 2021. Originally scheduled to take place from 24 July to 9 August 2020, the Tokyo Games were postponed until 2021 on 24 March 2020 as a result of the global COVID-19 pandemic, the only such postponement in the history of the Olympic Games (some previous editions had been cancelled but not rescheduled).', 2021, NULL, NULL, 2021, 8, 8, 'year', '2021', 92, 'https://en.wikipedia.org/wiki/2020_Summer_Olympics'),
  ('Q112967003', 'assassination of Shinzō Abe', 'On 8 July 2022, Shinzo Abe, the former prime minister of Japan and serving member of the Japanese House of Representatives, was assassinated while speaking at a political event outside Yamato-Saidaiji Station in Nara City, Nara Prefecture. Abe was delivering a campaign speech for a Liberal Democratic Party (LDP) candidate when he was fatally shot by 41-year-old Tetsuya Yamagami with an improvised firearm.', 2022, 7, 8, NULL, NULL, NULL, 'day', '8 July 2022', 77, 'https://en.wikipedia.org/wiki/Assassination_of_Shinzo_Abe'),
  ('Q124060919', '2024 Noto earthquake', 'On 1 January 2024, at 16:10:09 JST (07:10:09 UTC), a MJMA7.6 (Mw7.5) earthquake struck 6 km (3.7 mi) north-northeast of Suzu, located on the Noto Peninsula of Ishikawa Prefecture, Japan. The reverse-faulting shock achieved a maximum JMA seismic intensity of Shindo 7 and Modified Mercalli intensity of X–XI (Extreme).', 2024, 1, 1, NULL, NULL, NULL, 'day', '1 January 2024', 73, 'https://en.wikipedia.org/wiki/2024_Noto_earthquake'),
  ('Q124078312', '2024 Haneda Airport runway collision', 'On 2 January 2024, a runway collision occurred at Haneda Airport in Tokyo, Japan, involving an Airbus A350, operating as Japan Airlines Flight 516, and a De Havilland Canada Dash 8 operated by the Japan Coast Guard (JA722A). Flight 516 was a scheduled domestic passenger flight from New Chitose Airport near Sapporo, Japan, to Haneda Airport.', 2024, 1, 2, NULL, NULL, NULL, 'day', '2 January 2024', 65, 'https://en.wikipedia.org/wiki/2024_Haneda_Airport_runway_collision'),
  ('Q140735282', '2026 Kumamoto earthquake', 'On 28 July 2026 at approximately 16:27:15 JST (07:27:15 UTC), an earthquake struck Kumamoto Prefecture in southern Japan with a magnitude of Mww 6.8 (MJMA 7.1) at a depth of 10 km (6.2 mi), later revised to 16 km (9.9 mi). At least 38 people were killed and more than 368 were injured.', 2026, 7, 28, NULL, NULL, NULL, 'day', '28 July 2026', 64, 'https://en.wikipedia.org/wiki/2026_Kumamoto_earthquake');
